#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/stat.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>

#define MAX_PATH_LEN 256
#define BASE_DIR "/var/data/uploads/"

typedef struct {
    char normalized[MAX_PATH_LEN];
    size_t len;
    int validated;
} path_context_t;

/* Normalize path: collapse // and remove trailing slashes */
static int normalize_path(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    if (!input || !output) return -1;
    while (input[i] && j < outlen - 1) {
        if (input[i] == '/' && i > 0 && input[i-1] == '/') {
            i++;
            continue;
        }
        output[j++] = input[i++];
    }
    if (j > 1 && output[j-1] == '/') j--;
    output[j] = '\0';
    return 0;
}

/* Check for path traversal sequences */
static int contains_traversal(const char *path) {
    const char *p = path;
    while (*p) {
        if (p[0] == '.' && p[1] == '.') {
            if (p[2] == '/' || p[2] == '\0') return 1;
        }
        p++;
    }
    return 0;
}

/* Validate that resolved path stays within base directory */
static int validate_path_prefix(const char *fullpath) {
    char resolved[MAX_PATH_LEN];
    char base_resolved[MAX_PATH_LEN];

    if (!realpath(BASE_DIR, base_resolved)) return 0;

    /* Resolve the full target path - if file doesn't exist,
     * resolve parent directory and append filename */
    if (realpath(fullpath, resolved)) {
        size_t base_len = strlen(base_resolved);
        if (strncmp(resolved, base_resolved, base_len) != 0) return 0;
        if (resolved[base_len] != '/' && resolved[base_len] != '\0') return 0;
        return 1;
    }

    /* File doesn't exist - resolve parent dir */
    char dirpart[MAX_PATH_LEN];
    strncpy(dirpart, fullpath, MAX_PATH_LEN - 1);
    dirpart[MAX_PATH_LEN - 1] = '\0';
    char *last_slash = strrchr(dirpart, '/');
    if (!last_slash) return 0;
    *last_slash = '\0';

    if (!realpath(dirpart, resolved)) return 0;

    size_t base_len = strlen(base_resolved);
    if (strncmp(resolved, base_resolved, base_len) != 0) return 0;
    if (resolved[base_len] != '/' && resolved[base_len] != '\0') return 0;
    return 1;
}

/* Build full path from user input */
static int build_full_path(const char *user_input, char *result, size_t result_len) {
    path_context_t ctx;
    memset(&ctx, 0, sizeof(ctx));

    /* Step 1: normalize */
    if (normalize_path(user_input, ctx.normalized, MAX_PATH_LEN) != 0)
        return -1;
    ctx.len = strlen(ctx.normalized);

    /* Step 2: reject traversal */
    if (contains_traversal(ctx.normalized))
        return -1;

    /* Step 3: reject absolute paths */
    if (ctx.normalized[0] == '/')
        return -1;

    /* Step 4: reject null bytes */
    for (size_t i = 0; i < ctx.len; i++) {
        if (ctx.normalized[i] == '\0') return -1;
    }

    /* Step 5: reject any component starting with dot */
    const char *component = ctx.normalized;
    while (*component) {
        if (*component == '.') return -1;
        while (*component && *component != '/') component++;
        if (*component == '/') component++;
    }

    /* Step 6: build full path */
    int written = snprintf(result, result_len, "%s%s", BASE_DIR, ctx.normalized);
    if (written < 0 || (size_t)written >= result_len)
        return -1;

    ctx.validated = 1;
    return 0;
}

/* Write data to the validated path - uses O_NOFOLLOW to prevent symlink attacks */
static int write_file(const char *path, const char *data, size_t data_len) {
    /* Open with O_NOFOLLOW - fails if final component is symlink */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW, 0644);
    if (fd < 0) return -1;
    ssize_t w = write(fd, data, data_len);
    close(fd);
    return (w == (ssize_t)data_len) ? 0 : -1;
}

/*
 * Process an upload request.
 * Format: "UPLOAD <filename>\n<data>"
 */
int process_upload(const char *request, size_t req_len) {
    if (!request || req_len < 8) return -1;

    if (strncmp(request, "UPLOAD ", 7) != 0) return -1;

    const char *filename_start = request + 7;
    const char *newline = memchr(filename_start, '\n', req_len - 7);
    if (!newline) return -1;

    size_t fname_len = newline - filename_start;
    if (fname_len == 0 || fname_len >= MAX_PATH_LEN) return -1;

    char filename[MAX_PATH_LEN];
    memcpy(filename, filename_start, fname_len);
    filename[fname_len] = '\0';

    /* Validate and build path */
    char fullpath[MAX_PATH_LEN * 2];
    if (build_full_path(filename, fullpath, sizeof(fullpath)) != 0) {
        fprintf(stderr, "Path validation failed for: %s\n", filename);
        return -1;
    }

    /* Validate prefix AFTER building but BEFORE write */
    if (!validate_path_prefix(fullpath)) {
        fprintf(stderr, "Path prefix check failed: %s\n", fullpath);
        return -1;
    }

    const char *data = newline + 1;
    size_t data_len = req_len - (data - request);

    return write_file(fullpath, data, data_len);
}

/* Symlink-aware directory creation for user sandboxes */
int create_user_sandbox(const char *username) {
    if (!username) return -1;

    /* Validate username: alphanumeric only */
    for (const char *p = username; *p; p++) {
        if (!isalnum((unsigned char)*p)) return -1;
    }

    char sandbox_path[MAX_PATH_LEN];
    snprintf(sandbox_path, sizeof(sandbox_path), "%s%s", BASE_DIR, username);

    /* Check for existing symlink before mkdir */
    struct stat st;
    if (lstat(sandbox_path, &st) == 0) {
        if (S_ISLNK(st.st_mode)) return -1;
        if (!S_ISDIR(st.st_mode)) return -1;
        return 0;
    }

    if (mkdir(sandbox_path, 0755) != 0)
        return -1;

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <username> <filename> [data]\n", argv[0]);
        return 1;
    }

    const char *username = argv[1];
    const char *filename = argv[2];
    const char *data = argc > 3 ? argv[3] : "default content";

    if (create_user_sandbox(username) != 0) {
        fprintf(stderr, "Failed to create sandbox\n");
        return 1;
    }

    /* Build request */
    char request[1024];
    int rlen = snprintf(request, sizeof(request), "UPLOAD %s/%s\n%s",
                        username, filename, data);
    if (rlen < 0 || (size_t)rlen >= sizeof(request)) return 1;

    return process_upload(request, (size_t)rlen);
}
